declare p jsonb := '[{"book":"ulisse","id":"aldborough","collection":"core","name":"Aldborough House","noteHash":"f5b4e005c4175be37bc8b6e611115181","positionSource":"b179b92118bd573f1b40382ae7afe8563bf2093b80da948651e2d223d37c4b65","narrativeSource":"4b21d6beb743f1cd91fc18ccb38135012f4b35dd9fcf703dd46b9c08a5caf48c","description":{"status":"reviewed","reviewedAt":"2026-11-03","basis":"existing geographic and literary sources associated with this place","texts":{"en":"Father Conmee passes Aldborough House on his way towards North Strand.","it":"Padre Conmee passa presso Aldborough House dirigendosi verso North Strand.","fr":"Le père Conmee passe près d’Aldborough House en allant vers North Strand.","es":"El padre Conmee pasa junto a Aldborough House camino de North Strand."}}},{"book":"ulisse","id":"amiens","collection":"core","name":"Amiens Street Station","noteHash":"541da7645c0903d740835c643030b64f","positionSource":"720e393bd46a30a3b49285dc38e4a2087e8bf2b725f0ce62f41a7610cc1db827","narrativeSource":"ed61c4544b6423e234be10dbaacb2f8120499792fc4086733ca4e1bf13e76144","description":{"status":"reviewed","reviewedAt":"2026-11-03","basis":"existing geographic and literary sources associated with this place","texts":{"en":"Amiens Street Station is a railway station near Talbot Street.","it":"L’Amiens Street Station è una stazione ferroviaria presso Talbot Street.","fr":"Amiens Street Station est une gare proche de Talbot Street.","es":"Amiens Street Station es una estación ferroviaria cercana a Talbot Street."}}},{"book":"ulisse","id":"annesley","collection":"core","name":"Annesley Bridge","noteHash":"2b68b781de571372a92417274c8c182a","positionSource":"8ea1a17ac2aee20ef3881b1cdb043993184304387ef47cc3ca05b33da23b299f","narrativeSource":"4b21d6beb743f1cd91fc18ccb38135012f4b35dd9fcf703dd46b9c08a5caf48c","description":{"status":"reviewed","reviewedAt":"2026-11-03","basis":"existing geographic and literary sources associated with this place","texts":{"en":"Annesley Bridge is a landmark on Father Conmee’s tram journey.","it":"Annesley Bridge è un riferimento lungo il viaggio in tram di padre Conmee.","fr":"Annesley Bridge est un repère du trajet en tramway du père Conmee.","es":"Annesley Bridge es un punto de referencia en el viaje en tranvía del padre Conmee."}}},{"book":"ulisse","id":"baths","collection":"core","name":"Turkish and Warm Baths","noteHash":"5f9d1230a301a9700e8bfed2663ffb7f","positionSource":"725a97f6f2f76aa41a194da9567ac553f892c8f40114a5ba03b310b3ed11967c","narrativeSource":"26ba548e74b3c3ce82ed28a88e4e5cd51b18148e56fe112508ac7641fa0b8f57","description":{"status":"reviewed","reviewedAt":"2026-11-03","basis":"existing geographic and literary sources associated with this place","texts":{"en":"Bloom’s visit to the Turkish baths is recalled later; the exact establishment remains uncertain.","it":"La visita di Bloom ai bagni turchi è ricordata più avanti; l’identificazione dello stabilimento resta incerta.","fr":"La visite de Bloom aux bains turcs est rappelée plus tard ; l’établissement exact reste incertain.","es":"La visita de Bloom a los baños turcos se recuerda más adelante; el establecimiento exacto sigue siendo incierto."}}},{"book":"ulisse","id":"beaver","collection":"core","name":"Beaver Street","noteHash":"64ac83a092d025e4dd5a7f24e9170c7d","positionSource":"725a97f6f2f76aa41a194da9567ac553f892c8f40114a5ba03b310b3ed11967c","narrativeSource":"ed61c4544b6423e234be10dbaacb2f8120499792fc4086733ca4e1bf13e76144","description":{"status":"reviewed","reviewedAt":"2026-11-03","basis":"existing geographic and literary sources associated with this place","texts":{"en":"Beaver Street is the area where Stephen falls after the late-night clash.","it":"Beaver Street è la zona in cui Stephen cade dopo lo scontro notturno.","fr":"Beaver Street est le secteur où Stephen tombe après l’altercation nocturne.","es":"Beaver Street es la zona donde Stephen cae tras el altercado nocturno."}}},{"book":"ulisse","id":"bedford","collection":"core",